async function optimizeImage(file,max=1800,quality=.82){
  if(!file||!file.type.startsWith('image/'))return file;
  let source=null,width=0,height=0,cleanup=()=>{};
  try{
    if('createImageBitmap' in window){
      const bmp=await createImageBitmap(file);source=bmp;width=bmp.width;height=bmp.height;cleanup=()=>bmp.close?.();
    }else{
      const url=URL.createObjectURL(file),img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});source=img;width=img.naturalWidth;height=img.naturalHeight;cleanup=()=>URL.revokeObjectURL(url);
    }
    const scale=Math.min(1,max/Math.max(width,height)),w=Math.max(1,Math.round(width*scale)),h=Math.max(1,Math.round(height*scale));
    const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(source,0,0,w,h);
    const blob=await new Promise(r=>canvas.toBlob(r,'image/webp',quality));cleanup();
    return blob?new File([blob],(file.name.replace(/\.[^.]+$/,'')||'image')+'.webp',{type:'image/webp'}):file;
  }catch(e){try{cleanup()}catch{};return file}
}
async function upload(file,folder){
  const opt=await optimizeImage(file);const safe=(opt.name||'image.webp').replace(/[^a-zA-Z0-9._-]/g,'-'),path=folder+'/'+Date.now()+'-'+safe;
  const {error}=await sb.storage.from('nexus-media').upload(path,opt,{cacheControl:'31536000',upsert:false,contentType:opt.type});if(error)throw error;return sb.storage.from('nexus-media').getPublicUrl(path).data.publicUrl
}
