function contentEditor(x){
  panel.innerHTML='<div class="toolbar"><div><h2>'+(x.id?'Edit content':'Create content')+'</h2><p>Episodes accept YouTube URLs in the Media field.</p></div><button class="btn secondary" id="backContent">Back</button></div><form id="contentForm" class="formgrid"><div class="field"><label>Title</label><input name="title" value="'+esc(x.title||'')+'" required></div><div class="field"><label>Type</label><select name="category"><option value="story" '+(x.category==='story'?'selected':'')+'>Story</option><option value="episode" '+(x.category==='episode'?'selected':'')+'>Episode</option><option value="guide" '+(x.category==='guide'?'selected':'')+'>Guide</option></select></div><div class="field"><label>Author</label><input name="author" value="'+esc(x.author||'')+'"></div><div class="field"><label>Media / YouTube URL</label><input type="url" name="media_url" value="'+esc(x.media_url||'')+'"></div><div class="field full"><label>Tags</label><input name="tags" placeholder="BIM, estimating, careers" value="'+esc((x.tags||[]).join(', '))+'"></div><div class="field full"><label>Excerpt</label><textarea name="excerpt">'+esc(x.excerpt||'')+'</textarea></div><div class="field full"><label>Body</label><textarea name="body" style="min-height:220px">'+esc(x.body||'')+'</textarea></div><div class="field"><label>Cover image</label><input type="file" id="contentCover" accept="image/*"></div><div class="field full"><div class="publishbox"><div><b>Publishing</b><div class="muted">Drafts stay out of the public site.</div></div>'+(currentRole==='owner'?'<label><input type="checkbox" name="published" '+(x.published?'checked':'')+'> Published</label>':'<span class="status draft">Owner approval required</span>')+'</div></div><div class="field full"><button id="saveContent" class="btn">Save content</button></div></form>';
  backContent.onclick=contentView;contentForm.onsubmit=async e=>{e.preventDefault();busy(saveContent,true,'Saving…');const f=new FormData(contentForm);let image=x.image_url||null;try{if(contentCover.files[0])image=await upload(contentCover.files[0],'content')}catch(err){busy(saveContent,false,'Save content');return toast(err.message)}const pub=currentRole==='owner'?contentForm.published.checked:false,payload={title:f.get('title').trim(),slug:x.slug||slugify(f.get('title'))+'-'+Date.now().toString().slice(-5),category:f.get('category'),author:f.get('author').trim(),excerpt:f.get('excerpt').trim(),body:f.get('body').trim(),media_url:f.get('media_url').trim()||null,image_url:image,tags:tags(f.get('tags')),published:pub,published_at:pub?(x.published_at||new Date().toISOString()):null};const cmd=x.id?sb.from('stories').update(payload).eq('id',x.id):sb.from('stories').insert(payload);const {error}=await cmd;if(error){busy(saveContent,false,'Save content');return toast(error.message)}toast('Content saved.');contentView()}
}
