async function brandingView(){
  const {data:s,error}=await sb.from('site_settings').select('*').eq('id',1).single();if(error)return panel.innerHTML='<div class="empty">'+esc(error.message)+'</div>';
  panel.innerHTML='<div class="toolbar"><div><h2>Branding & Logo</h2><p>This controls the public NEXUS lockup and core site messaging.</p></div><button class="btn secondary" id="backGeneral">Back to General Settings</button></div><form id="brandingForm" class="formgrid"><div class="field"><label>Brand name</label><input name="brand_name" value="'+esc(s.brand_name||'NEXUS')+'"></div><div class="field"><label>Tagline</label><input name="brand_tagline" value="'+esc(s.brand_tagline||'Construction Without Borders')+'"></div><div class="field"><label>Logo image</label><input type="file" id="brandLogoFile" accept="image/png,image/jpeg,image/webp,image/svg+xml"></div><div class="field"><label>Logo alt text</label><input name="logo_alt" value="'+esc(s.logo_alt||s.brand_name||'NEXUS')+'"></div><div class="field full"><div class="sectionbox"><h3>Current logo</h3><div id="logoPreview" style="min-height:70px;display:flex;align-items:center;gap:16px">'+(s.logo_url?'<img src="'+esc(s.logo_url)+'" alt="'+esc(s.logo_alt||'NEXUS')+'" style="max-width:220px;max-height:70px;object-fit:contain">':'<b style="font-size:28px;color:var(--p)">'+esc(s.brand_name||'NEXUS')+'</b>')+'</div><label style="display:block;margin-top:12px"><input type="checkbox" name="remove_logo"> Remove uploaded logo and use text brand</label></div></div><div class="field"><label>About heading</label><input name="about_heading" value="'+esc(s.about_heading||'Construction without borders.')+'"></div><div class="field"><label>Contact email</label><input type="email" name="contact_email" value="'+esc(s.contact_email||'')+'"></div><div class="field full"><label>About main text</label><textarea name="about_text" rows="5">'+esc(s.about_text||'')+'</textarea></div><div class="field"><label>Join heading</label><input name="join_heading" value="'+esc(s.join_heading||'Join NEXUS')+'"></div><div class="field"><label>Join intro</label><input name="join_intro" value="'+esc(s.join_intro||'Choose how you would like to connect with the NEXUS community.')+'"></div><div class="field full"><button class="btn" id="saveBranding">Save branding & website identity</button></div></form>';
  backGeneral.onclick=generalView;
  brandLogoFile.onchange=()=>{const file=brandLogoFile.files[0];if(file){const url=URL.createObjectURL(file);logoPreview.innerHTML='<img src="'+url+'" alt="Logo preview" style="max-width:220px;max-height:70px;object-fit:contain">'}};
  brandingForm.onsubmit=async e=>{e.preventDefault();busy(saveBranding,true,'Saving…');const fd=new FormData(brandingForm);let logo=s.logo_url||null;try{if(fd.get('remove_logo'))logo=null;else if(brandLogoFile.files[0])logo=await upload(brandLogoFile.files[0],'branding')}catch(err){busy(saveBranding,false,'Save branding & website identity');return toast(err.message)}
    const payload={brand_name:fd.get('brand_name').trim()||'NEXUS',brand_tagline:fd.get('brand_tagline').trim()||'Construction Without Borders',logo_url:logo,logo_alt:fd.get('logo_alt').trim()||fd.get('brand_name').trim()||'NEXUS',about_heading:fd.get('about_heading').trim(),about_text:fd.get('about_text').trim(),contact_email:fd.get('contact_email').trim()||null,join_heading:fd.get('join_heading').trim()||'Join NEXUS',join_intro:fd.get('join_intro').trim()||'Choose how you would like to connect with the NEXUS community.',updated_at:new Date().toISOString()};
    const {error}=await sb.from('site_settings').update(payload).eq('id',1);busy(saveBranding,false,'Save branding & website identity');if(error)return toast(error.message);sessionStorage.removeItem('nexus_site_bundle_v3');alert('Branding saved. The logo and tagline will now be used across the public site.');brandingView()
  }
}
